cat > check_altitude.py << 'EOL'
import subprocess
import re

# Function to decode the base64 encoded domains
def decode_base64(encoded):
    try:
        cmd = ["echo", encoded, "|", "base64", "-d"]
        result = subprocess.run(" ".join(cmd), shell=True, capture_output=True, text=True)
        return result.stdout.strip()
    except:
        return None

# Extract altitude from decoded strings
def extract_altitude(decoded):
    if not decoded:
        return None

    match = re.search(r'(\d+\.\d+),ft', decoded)
    if match:
        return float(match.group(1))
    return None

# Read the encoded altitude domains
altitudes = []
with open('altitude_encoded.txt', 'r') as f:
    for line in f:
        encoded = line.strip()
        decoded = decode_base64(encoded)
        altitude = extract_altitude(decoded)
        if altitude:
            altitudes.append((encoded, decoded, altitude))

# Sort by altitude
altitudes.sort(key=lambda x: x[2])

# Print the altitudes
print("Altitudes in ascending order:")
for encoded, decoded, altitude in altitudes:
    print(f"{encoded}: {decoded} -> {altitude}")

# Look for patterns or convert to ASCII
if altitudes:
    alt_values = [alt[2] for alt in altitudes]
    print("\nAltitude values:", alt_values)

    # Check if these could be ASCII values
    try:
        ascii_chars = [chr(int(alt % 1000)) for alt in alt_values]
        ascii_message = ''.join(ascii_chars)
        print("Possible ASCII message:", ascii_message)
    except:
        print("Could not convert to ASCII")

    # Check if these could be a series of XY coordinates
    if len(alt_values) > 1:
        try:
            sequence = [int(alt % 1000) for alt in alt_values]
            print("Possible coordinate sequence:", sequence)
        except:
            print("Could not extract sequence")
EOL

python3 check_altitude.py
